/**
 * Builds the expert-validation form for the Rice MMKG competency
 * questions in Google Forms.
 *
 * Generated by scripts/stage5_questionnaire.py - do not hand-edit;
 * change ITEMS in that script and regenerate, or the form will drift
 * from cq_stage5_items.csv and responses will no longer join to the key.
 *
 * To use: open script.google.com, create a new project, paste this in,
 * and run createValidationForm() once. It prints the form URL to the
 * execution log. Item order is fixed (seed 20260907)
 * and must not be shuffled again in the form settings.
 */

// Collecting a rater identity is required to compute inter-rater
// agreement - without it, ratings cannot be attributed. It is also a
// consent decision, so it is left explicit rather than defaulted.
var COLLECT_EMAIL = false;   // set true to use Google account emails

var TITLE = 'Kuesioner Validasi Pakar - Pertanyaan Kompetensi Knowledge Graph Hama dan Penyakit Padi';

var INTRO = [
  'Kami sedang MERANCANG sebuah basis pengetahuan (knowledge graph) tentang hama dan penyakit padi, yang akan menggabungkan pengetahuan dari literatur dengan citra gejala di lapangan.',
  '',
  'Tahap yang sedang kami kerjakan adalah PENENTUAN CAKUPAN: menetapkan pertanyaan-pertanyaan apa saja yang nantinya harus dapat dijawab. Dalam rekayasa ontologi, daftar semacam ini disebut competency questions dan berfungsi sebagai spesifikasi kebutuhan - ditetapkan SEBELUM sistemnya dibangun.',
  '',
  'Belum ada sistem yang perlu Anda coba, dan Anda tidak perlu menjawab pertanyaan-pertanyaannya. Yang kami minta adalah penilaian Anda sebagai pakar atas pertanyaannya sendiri.',
  '',
  'Pengisian diperkirakan memakan waktu 20-30 menit.'
].join('\n');

var LEGEND = [
  'Relevansi - seberapa penting pertanyaan ini bagi praktik diagnosis dan pengelolaan hama serta penyakit padi?  (1 = tidak relevan, 5 = sangat penting)',
  'Kejelasan - apakah pertanyaan ini dirumuskan dengan jelas dan tidak menimbulkan tafsir ganda?  (1 = sangat kabur, 5 = sangat jelas)'
].join('\n');

var SCALE = ['1 (rendah)', '2', '3', '4', '5 (tinggi)'];
var ROWS = ['Relevansi', 'Kejelasan'];

// [item number, question (Indonesian), original English wording]
var ITEMS = [
  [1, 'Fase pertumbuhan apa yang tampak dari citra kanopi utuh?',
   'Which growth stage is visually manifest in a whole-canopy image?'],
  [2, 'Pada kondisi apa saja anotasi hasil model dan anotasi pakar berbeda?',
   'On which conditions do model-generated and expert image annotations disagree?'],
  [3, 'Seberapa berat tingkat kerusakan yang tercatat pada suatu citra?',
   'How severe is the damage recorded in a given image?'],
  [4, 'Siapa atau apa yang membuat anotasi pada suatu citra, dan dengan tingkat keyakinan berapa?',
   'Who or what produced the annotation of a given image, and with what confidence?'],
  [5, 'Gejala apa saja yang muncul bersamaan pada satu tanaman dalam satu citra?',
   'Which symptoms co-occur on the same plant within a single image?'],
  [6, 'Gejala apa yang dideskripsikan di literatur dan memiliki bukti citra pendukung, dan mana yang tidak?',
   'Which symptoms described in the literature have supporting image evidence, and which do not?'],
  [7, 'Spesies vektor apa yang menularkan Rice Tungro Bacilliform Virus, dan melalui mekanisme penularan apa?',
   'Which vector species transmits Rice Tungro Bacilliform Virus, and by which transmission mode?'],
  [8, 'Patogen apa yang menyebabkan penyakit blas (rice blast), dan termasuk kelompok taksonomi apa (jamur, bakteri, virus)?',
   'Which pathogen causes Rice Blast, and to which taxonomic group (fungus, bacterium, virus) does it belong?'],
  [9, 'Berapa jumlah citra untuk tiap kondisi, organ tanaman, dan jenis pengambilan (lapangan atau jarak dekat)?',
   'How many images exist for each condition, plant organ, and capture type (field versus close-up)?'],
  [10, 'Citra mana saja yang dianotasi menunjukkan serangan hispa?',
   'Which images are annotated as showing Hispa damage?'],
  [11, 'Kondisi lingkungan apa yang dilaporkan memicu berkembangnya hawar pelepah (sheath blight)?',
   'Which environmental conditions are reported to favour Sheath Blight?'],
  [12, 'Ciri visual apa yang membedakan bercak coklat (brown spot) dari penyakit blas (rice blast)?',
   'Which visual features separate Brown Spot from Rice Blast?'],
  [13, 'Pada fase pertumbuhan apa wereng batang coklat dilaporkan paling merusak?',
   'At which growth stages is Brown Planthopper reported as most damaging?'],
  [14, 'Gejala apa saja yang ditimbulkan hawar daun bakteri (bacterial leaf blight), pada organ tanaman apa, dan pada fase pertumbuhan apa?',
   'Which symptoms does Bacterial Leaf Blight produce, on which plant organ, and at which growth stage?'],
  [15, 'Penyakit atau hama apa yang paling didukung oleh bukti visual pada citra yang menunjukkan bercak coklat di helai daun?',
   'Which disease or pest is best supported by the visual evidence in an image showing brown lesions on the leaf blade?'],
  [16, 'Penyakit apa saja yang gejalanya tumpang tindih dengan bercak coklat (brown spot), dan gejala apa yang membedakannya?',
   'Which diseases share symptoms with Brown Spot, and which symptoms discriminate between them?'],
  [17, 'Ciri apa yang membedakan gangguan hara seperti defisiensi seng dari penyakit blas, ketika gejala yang tampak mirip?',
   'Which features distinguish a nutritional disorder such as zinc deficiency from Rice Blast, when the visible symptoms are similar?'],
  [18, 'Gejala apa saja yang dianotasi pada suatu citra?',
   'Which visible symptoms are annotated in a given image?'],
  [19, 'Tindakan apa yang direkomendasikan literatur untuk kondisi yang teridentifikasi dari citra sebagai hawar pelepah?',
   'Which treatment does the literature prescribe for a condition identified from an image as Sheath Blight?'],
  [20, 'Penyakit apa dalam literatur yang cocok dengan gejala teranotasi pada citra yang menunjukkan garis kebasahan (water-soaked streak)?',
   'Which disease described in the literature matches the symptoms annotated in an image showing water-soaked streaks?'],
  [21, 'Organ tanaman apa (daun, pelepah, batang, malai) yang tampak pada suatu citra?',
   'Which plant organ (leaf, sheath, stem, panicle) is depicted in a given image?'],
  [22, 'Tindakan pengendalian apa yang direkomendasikan untuk penggerek batang, termasuk kategori apa (kimiawi, hayati, kultur teknis), dan bersumber dari rujukan apa?',
   'Which control measures are recommended for Stem Borer, of which management category (chemical, biological, cultural), and on which source authority?'],
  [23, 'Musuh alami apa saja yang tercatat sebagai predator atau parasitoid wereng batang coklat?',
   'Which natural enemies are documented as predators or parasitoids of Brown Planthopper?'],
];

function createValidationForm() {
  var form = FormApp.create(TITLE);
  form.setDescription(INTRO);
  form.setCollectEmail(COLLECT_EMAIL);
  form.setProgressBar(true);
  form.setShuffleQuestions(false);   // order is fixed by design

  for (var i = 0; i < ITEMS.length; i++) {
    if (i % 6 === 0) {
      var page = form.addPageBreakItem()
        .setTitle('Pertanyaan ' + (i + 1) + '-' +
                  Math.min(i + 6, ITEMS.length));
      page.setHelpText(LEGEND);
    }
    var it = ITEMS[i];
    form.addGridItem()
      .setTitle(it[0] + '. ' + it[1])
      .setHelpText(it[2])
      .setRows(ROWS)
      .setColumns(SCALE)
      .setRequired(true);
    form.addTextItem()
      .setTitle('Catatan untuk pertanyaan ' + it[0] + ' (opsional)')
      .setHelpText('Mohon diisi terutama bila Anda memberi nilai rendah, atau bila istilah yang kami gunakan keliru menurut praktik di lapangan.')
      .setRequired(false);
  }

  form.addPageBreakItem()
    .setTitle('Pertanyaan yang belum tercakup')
    .setHelpText('Bagian ini sama pentingnya dengan penilaian di atas. Daftar tersebut kami susun dari sumber otomatis, sehingga besar kemungkinan ada hal yang penting di lapangan namun tidak muncul di sana.');
  form.addParagraphTextItem()
    .setTitle('Menurut Anda, pertanyaan apa yang seharusnya masuk dalam cakupan basis pengetahuan ini, tetapi belum ada dalam daftar di atas?')
    .setHelpText('Tuliskan satu pertanyaan per baris. Boleh lebih dari satu, boleh juga dikosongkan.')
    .setRequired(false);

  form.addPageBreakItem().setTitle('Identitas penilai');
  form.addTextItem().setTitle('Nama').setRequired(true);
  form.addTextItem().setTitle('Institusi').setRequired(true);
  form.addTextItem().setTitle('Bidang keahlian').setRequired(true);
  form.addTextItem()
    .setTitle('Lama pengalaman di bidang padi (tahun)')
    .setRequired(true);

  Logger.log('Isi form  : ' + form.getPublishedUrl());
  Logger.log('Edit form : ' + form.getEditUrl());
}
